/* Entomologie für Fliegenfischer – Daten
   Saison = gemäßigte Nordhalbkugel (Mitteleuropa-Basis), Stufen 0–3
   Geo    = Vorkommen / Bedeutung je Weltregion, Stufen 0–3                */
"use strict";

const MONTHS = ["Jan","Feb","Mär","Apr","Mai","Jun","Jul","Aug","Sep","Okt","Nov","Dez"];
const MONTHS_LONG = ["Januar","Februar","März","April","Mai","Juni","Juli","August","September","Oktober","November","Dezember"];

/* "4-5:3,6:1" -> [0,0,0,3,3,1,0,0,0,0,0,0] */
const S = str => {
  const a = Array(12).fill(0);
  str.split(",").forEach(seg => {
    const [r, v] = seg.trim().split(":");
    const [from, to] = r.split("-").map(Number);
    for (let m = from; m <= (to || from); m++) a[m - 1] = +v;
  });
  return a;
};
/* "NA3 MA2 ..." -> {NA:3, MA:2, ...} */
const R = str => {
  const o = {NA:0,MA:0,SA:0,EU:0,NAS:0,ME:0,AF:0,AS:0,OC:0};
  str.trim().split(/\s+/).forEach(t => { const m = t.match(/^([A-Z]+)(\d)$/); if (m) o[m[1]] = +m[2]; });
  return o;
};

